const result = {};
for (const key in form) {
    if (form.hasOwnProperty(key)) {
        const titleCaseKey = key.charAt(0).toUpperCase() + key.slice(1);

        if (form[key] === "") continue;

        if (/^(is|need|with|active)/i.test(key) && method === "POST") {
            result[titleCaseKey] = form[key] || false;
        } else if (key.includes("fiscalYear") && form[key] && typeof form[key] !== "string") {
            const parsedDate = $ctrl.utils.parseDate(form[key]).split("-");
            const month = parsedDate[1];
            const day = parsedDate[2].split(" ")[0];
            result[titleCaseKey] = month + "-" + day;
        } else {
            result[titleCaseKey] = form[key];
        }
    }
}
return result;

