$ctrl.isUpdating = true;
const entityId = $ctrl.uiState.selectedEntity?.Id;

// Keep form open with updated info and reselect table row
async function updateEditForm() {
    const tableRowIndex = $ctrl.tabStore[$ctrl.uiState.currentTab.name].data.findIndex(entity => entity.Id === entityId);
    if (tableRowIndex === -1) {
        throw new Error(`Entity not found in table`);
    }

    $ctrl.tabStore[$ctrl.uiState.currentTab.name].data[tableRowIndex] = $ctrl.uiState.selectedEntity = $ctrl.utils.buildUpdatedEntityData($ctrl[$ctrl.tabConfig[$ctrl.uiState.currentTab.name].form], $ctrl.uiState.selectedEntity);

    // Hydrate fields based on updated Ids on dropdown selection
    const hydratedEntity = await $ctrl.referenceDataService.hydrateEntity(
        $ctrl.tabStore[$ctrl.uiState.currentTab.name].data[tableRowIndex]
    );

    const tabConfig = $ctrl.tabConfig[$ctrl.uiState.currentTab.name]
    $ctrl.tabStore[$ctrl.uiState.currentTab.name].data[tableRowIndex] = $ctrl.uiState.selectedEntity = hydratedEntity
    $ctrl.uiState.selectedEntityName = (typeof tabConfig.getName === "function") 
    ? tabConfig.getName(hydratedEntity) 
    : hydratedEntity[tabConfig.entityNameKey];

    $ctrl.$timeout(() => {
        $ctrl.utils.setSelectedBelliniTableRow(tableRowIndex);
    });
    $ctrl.handlers.onEditInit();
    const formToReset = document.querySelector('.form');
    if(formToReset) {
        formToReset.scrollTop = 0;
    }
}

